@startuml

class Hospital {}

class Doctor {
  + Name : string
}

class Patient {}

class Problem {}

class ExaminationType {
  + Name : string
}

class TreatmentPlan {
  + ProblemType : string
}

class Diagnosis {
  + Date : date
}

class ActualTreatment {
  + DeviationStatus : boolean
}

class MedicalAction {
  + Description : string
}

class Examination {
  + Date : date
}

Hospital "1" -- "*" Doctor : employs
Hospital "1" -- "*" ExaminationType : has permission for
Hospital "1" -- "*" Diagnosis : hosts
Hospital "1" -- "*" ActualTreatment : hosts

Doctor "1" -- "*" Diagnosis : poses
Patient "1" -- "*" Diagnosis : receives
Problem "1" -- "*" TreatmentPlan : defines
TreatmentPlan "1" -- "*" ExaminationType : advises

Diagnosis "1" -- "1" ActualTreatment : results in
ActualTreatment "1" -- "*" Examination : consists of
ActualTreatment "1" -- "*" MedicalAction : consists of
ActualTreatment "1" -- "0..1" TreatmentPlan : follows

Examination "*" -- "1" ExaminationType : is a type of
Examination "0..1" -- "0..1" Hospital : performed at

@enduml

